SELECT id, name, email, phone, DATE_FORMAT(birth_date, '%Y-%m-%d') AS birthDate, address, status, DATE_FORMAT(created_at, '%Y-%m-%d %H:%i') AS createdAt FROM member
name LIKE CONCAT('%', #{keyword}, '%') OR email LIKE CONCAT('%', #{keyword}, '%') OR phone LIKE CONCAT('%', #{keyword}, '%')
ORDER BY created_at DESC LIMIT #{offset}, #{limit}
